/// <summary>
/// PaffH 26.10.23
/// </summary>
internal final class NDXProdIdentCopy1Wizard extends SysWizard
{
    NDXProdIdentProcedureTable    nDXProdIdentProcedureTable;
    InventTable inventTable;

}

Method.Source:
/// <summary>
/// PaffH 26.10.23
/// </summary>
/// <returns>formName</returns>
public formName formName()
{
    return formStr(NDXProdIdentCopy1Wizard);
}

/// <summary>
/// PaffH 26.10.23
/// </summary>
/// <returns>boolean</returns>
public boolean validate()
{
    return true;
}

/// <summary>
/// PaffH 26.10.23
/// </summary>
/// <param name = "args">Args</param>
public static void main(Args args)
{
    NDXProdIdentCopy1Wizard wizard = new NDXProdIdentCopy1Wizard();

    if (args.dataset() == tableNum(InventTable))
    {
        InventTable locInventTable = args.record();
        wizard.parmInventTable(locInventTable);

        NDXProdIdentProcedureTable locNDXProdIdentProcedureTable = NDXProdIdentProcedureTable::findInventTable(locInventTable.RecId);
        wizard.parmNDXProdIdentProcedureTable(locNDXProdIdentProcedureTable);
    }

    if (wizard.prompt())
    {
        wizard.run();
    }
}

/// <summary>
/// PaffH 27.10.23
/// </summary>
/// <param name = "_nDXProdIdentProcedureTable">NDXProdIdentProcedureTable</param>
/// <returns>NDXProdIdentProcedureTable</returns>
public NDXProdIdentProcedureTable parmNDXProdIdentProcedureTable(NDXProdIdentProcedureTable _nDXProdIdentProcedureTable = nDXProdIdentProcedureTable)
{
    nDXProdIdentProcedureTable = _nDXProdIdentProcedureTable;
    return nDXProdIdentProcedureTable;
}

/// <summary>
/// PaffH 28.10.23
/// </summary>
/// <param name = "_inventTable">InventTable</param>
/// <returns>InventTable</returns>
public InventTable parmInventTable(InventTable _inventTable = InventTable)
{
    inventTable = _inventTable;
    return inventTable;
}
